hudson.tasks.Shell.command:
#!/usr/bin/env bash set -euo pipefail
ENABLE_OPEN_ACCESS="${ENABLE_OPEN_ACCESS:-false}" ENABLE_EXPLORE_WITHOUT_LOGIN="${ENABLE_EXPLORE_WITHOUT_LOGIN:-false}" CONFIRM_AUTH_HPDS_PUBLIC="${CONFIRM_AUTH_HPDS_PUBLIC:-false}"
if [ "$ENABLE_EXPLORE_WITHOUT_LOGIN" = "true" ] && [ "$CONFIRM_AUTH_HPDS_PUBLIC" != "true" ]; then echo "ERROR: CONFIRM_AUTH_HPDS_PUBLIC must be true when ENABLE_EXPLORE_WITHOUT_LOGIN=true." exit 1 fi
if [ "$ENABLE_OPEN_ACCESS" = "true" ] || [ "$ENABLE_EXPLORE_WITHOUT_LOGIN" = "true" ]; then ENABLE_ANONYMOUS_REQUESTS=true else ENABLE_ANONYMOUS_REQUESTS=false fi
CONFIG_DIR="${DOCKER_CONFIG_DIR:-/usr/local/docker-config}" HTTPD_ENV="$CONFIG_DIR/httpd/httpd.env" PSAMA_ENV="$CONFIG_DIR/psama/psama.env" GATEWAY_ENV="$CONFIG_DIR/gateway/gateway.env"
for required_file in "$HTTPD_ENV" "$PSAMA_ENV" "$GATEWAY_ENV"; do if [ ! -f "$required_file" ]; then echo "ERROR: Required configuration file not found: $required_file" exit 1 fi done
upsert_env() { local key=$1 local value=$2 local env_file=$3 local temp_file="${env_file}.tmp.$$"
awk -v key="$key" -v value="$value" ' BEGIN { found = 0 } index($0, key "=") == 1 { if (!found) print key "=" value found = 1 next } { print } END { if (!found) print key "=" value } ' "$env_file" > "$temp_file" cat "$temp_file" > "$env_file" rm "$temp_file" }
read_env() { local key=$1 local env_file=$2 sed -n "s/^${key}=//p" "$env_file" }
validate_env() { local key=$1 local expected=$2 local env_file=$3 local actual actual="$(read_env "$key" "$env_file")" if [ "$actual" != "$expected" ]; then echo "ERROR: $env_file contains $key=$actual; expected $key=$expected." exit 1 fi }
upsert_env VITE_OPEN "$ENABLE_ANONYMOUS_REQUESTS" "$HTTPD_ENV" upsert_env VITE_DISCOVER "$ENABLE_OPEN_ACCESS" "$HTTPD_ENV" upsert_env VITE_OPEN_EXPLORER "$ENABLE_EXPLORE_WITHOUT_LOGIN" "$HTTPD_ENV" upsert_env OPEN_IDP_PROVIDER_IS_ENABLED "$ENABLE_ANONYMOUS_REQUESTS" "$PSAMA_ENV" upsert_env GATEWAY_OPEN_ACCESS_ENABLED "$ENABLE_ANONYMOUS_REQUESTS" "$GATEWAY_ENV"
validate_env VITE_OPEN "$ENABLE_ANONYMOUS_REQUESTS" "$HTTPD_ENV" validate_env VITE_DISCOVER "$ENABLE_OPEN_ACCESS" "$HTTPD_ENV" validate_env VITE_OPEN_EXPLORER "$ENABLE_EXPLORE_WITHOUT_LOGIN" "$HTTPD_ENV" validate_env OPEN_IDP_PROVIDER_IS_ENABLED "$ENABLE_ANONYMOUS_REQUESTS" "$PSAMA_ENV" validate_env GATEWAY_OPEN_ACCESS_ENABLED "$ENABLE_ANONYMOUS_REQUESTS" "$GATEWAY_ENV"
echo "Open Access/Discover: $ENABLE_OPEN_ACCESS" echo "Explore Without Login: $ENABLE_EXPLORE_WITHOUT_LOGIN" echo "Anonymous requests: $ENABLE_ANONYMOUS_REQUESTS" echo "Configuration written and validated."
